<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('ActivityOffline/manage')}">分类列表</a>|					<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('ActivityOffline/add')}','添加分类',800,560,true,false,false,addbtn,'add',true);">添加分类</a>					<a href="{pigcms{:U('ActivityOffline/activity_list')}">线下活动列表</a>|					<a href="" class="on">退款审核列表</a>					<a href="{pigcms{:U('ActivityOffline/ActivityOffline_config')}">配置项</a>|				</ul>			</div>			<table class="search_table" width="100%">			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>						</colgroup>						<thead>							<tr>								<th>编号</th>								<th>姓名</th>								<th>手机号</th>								<th>应退金额</th>								<th>添加时间</th>								<th>状态</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="!empty($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$vo.nickname}</td>										<td>{pigcms{$vo.phone}</td>										<td>{pigcms{$vo.money}</td>										<td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>										<td>											<if condition="$vo.status eq 1">												<font style="color: red;">未审核</font>											</if>											</td>										<td class="textcenter"><a href="javascript:void(0);" onclick="toCheck('{pigcms{$vo.id}','{pigcms{$vo.order_id}','{pigcms{$vo.join_id}');">审核</a>&nbsp; | &nbsp;<a href="javascript:void(0);" onclick="toDelItem({pigcms{$vo.id});">删除</a></td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="9">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><script type="text/javascript">layer.config({extend: 'extend/layer.ext.js'});function toCheck(id,order_id,join_id){    layer.confirm('是否审核通过?', {                       btn: ['通过', '驳回']        ,offset: '400px'       , btn1:function(){       	layer.prompt({			  formType: 0,			  title: '退款金额:',			  offset: '400px',			  maxlength:255			}, function(refund_money){//这里需要接入支付				$.post("{pigcms{:U('ActivityOffline/mobile_refund')}",{'order_id':order_id,'id':id,'join_id':join_id,'refund_money':refund_money},function(data){					if(data.status == 1){//成功                    	layer.msg(data.url, {offset: '400px',icon: 1,time: 3000},function(){location.reload()});					}else{						layer.msg(data.url, {offset: '400px',icon: 2,time: 3000},function(){location.reload()});					}                },'JSON');			});        }        , btn2: function () {			$.post("{pigcms{:U('ActivityOffline/verifyRefund')}",{'id':id,'status':2},function(data){			  data=parseInt(data);			  if(!data){		            layer.msg('审核未通过!', {offset: '400px',icon: 1,time: 2000},function(){location.reload()});			   }else{			   		layer.msg('操作失败,请重试!!', {offset: '400px',icon: 2,time: 2000},function(){location.reload()});			   }		    },'JSON');        }    });}			/***删除***/function toDelItem(id){    if(confirm('您确定删除此项吗？')){    $.post("{pigcms{:U('ActivityOffline/del_refund')}",{id:id},function(data){	  data=parseInt(data);	  if(!data){          window.location.reload();	   }     },'JSON');   }else{     return false;   }}</script><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js?{pigcms{:time()}"></script><include file="Public:footer"/>